const parserName = "dummy-toml-plugin-parser-name";
const astFormat = "dummy-toml-plugin";

export default {
  languages: [
    {
      name: "dummy-toml",
      parsers: [parserName],
      extensions: [".dummy-toml"],
    },
  ],
  parsers: {
    [parserName]: {
      parse: (text) => ({ value: text }),
      astFormat,
    },
  },
  printers: {
    [astFormat]: {
      print: (path) =>
        `!!! Formatted by with '${parserName}' parser\n${path.getValue().value.trim()}\n`,
    },
  },
};
